const TARIFAS = { palermo: 1200, flores: 1500, almagro: 1100 };
const LIMITE_PESADO_KG = 20; // el contrato dice «más de 20 kg»: el límite no cuenta
const RECARGO_PESADO = 800;

function costoEnvio(zona, kg) {
  const base = TARIFAS[zona];
  if (base === undefined) throw new Error(`zona desconocida: ${zona}`);
  const recargo = kg > LIMITE_PESADO_KG ? RECARGO_PESADO : 0;
  return base + recargo;
}

for (const kg of [5, 20, 20.01, 20.5, 35]) {
  console.log(kg + " kg a Palermo:", costoEnvio("palermo", kg));
}
